INSERT INTO answer_sets (book_id, chapter, title) VALUES (14, 1, 'Упражнения: абстракция и биты');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 1, 0, 'Сколько различных значений можно записать в 10 битах?', '["1024"]', 'Каждый бит удваивает число вариантов: 2 в степени 10.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 1, 1, 'Сколько битов нужно, чтобы пронумеровать 1000 различных предметов?', '["10"]', 'Найдите наименьшее n, для которого 2ⁿ не меньше 1000.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 1, 2, 'Какое наибольшее целое число без знака помещается в один байт?', '["255"]', 'Всего значений 256, а считаем с нуля.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 1, 3, 'Сколько байтов в 3 КиБ (1 КиБ = 1024 байта)?', '["3072"]', 'Умножьте 3 на 1024.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 1, 4, 'Тактовая частота процессора 4 ГГц. Чему равен период такта в пикосекундах?', '["250"]', 'Период — единица, делённая на частоту; 1 / 4 ГГц = 0,25 нс.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 1, 5, 'Сколько адресных линий нужно, чтобы адресовать 4 ГиБ памяти по одному байту?', '["32"]', '4 ГиБ — это 2³² байтов.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 1, 6, 'Сколько различных состояний у трёх выключателей, каждый из которых включён или выключен?', '["8"]', 'Два состояния на выключатель, выключателей три.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 1, 7, 'Относится ли набор регистров, видимых программисту, к архитектуре, а не к микроархитектуре? Ответьте «да» или «нет».', '["да"]', 'Архитектура — это компьютер глазами программиста: команды и регистры.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 1, 8, 'В системе пять модулей, в каждом по четыре подмодуля, а в каждом подмодуле по три детали. Сколько деталей на нижнем уровне?', '["60"]', 'Количества на уровнях иерархии перемножаются.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 1, 9, 'Сколько килобит (1 кбит = 1000 бит) в 2 килобайтах (1 КБ = 1000 байт)?', '["16"]', 'В байте 8 бит.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (14, 2, 'Упражнения: транзистор и КМОП');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 2, 0, 'В КМОП-схеме на затвор nMOS-транзистора подана логическая единица. Транзистор открыт? Ответьте «да» или «нет».', '["да"]', 'nMOS проводит при высоком напряжении на затворе, pMOS — при низком.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 2, 1, 'Сколько транзисторов в КМОП-инверторе?', '["2"]', 'Один pMOS подтягивает к питанию, один nMOS — к земле.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 2, 2, 'Сколько транзисторов в КМОП-элементе И-НЕ на два входа?', '["4"]', 'Два nMOS последовательно и два pMOS параллельно.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 2, 3, 'Сколько транзисторов в КМОП-элементе И-НЕ на четыре входа?', '["8"]', 'Для каждого входа нужен один nMOS и один pMOS.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 2, 4, 'Сколько nMOS-транзисторов в КМОП-элементе ИЛИ-НЕ на два входа?', '["2"]', 'В цепи, тянущей к земле, они стоят параллельно.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 2, 5, 'Динамическая мощность считается как C · V² · f. Ёмкость 1 нФ, напряжение 1,2 В, частота 2 ГГц. Сколько ватт? (в этом упражнении активность переключений принимается за 1)', '["2.88"]', 'Подставьте значения в СИ: 1 нФ = 1·10⁻⁹ Ф, 2 ГГц = 2·10⁹ Гц.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 2, 6, 'Во сколько раз уменьшится динамическая мощность, если снизить напряжение питания вдвое при той же частоте?', '["4"]', 'Мощность пропорциональна квадрату напряжения.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 2, 7, 'Запас помехоустойчивости по низкому уровню равен V_IL − V_OL. Чему он равен в вольтах при V_OL = 0,4 В и V_IL = 1,0 В?', '["0.6"]', 'Просто вычтите.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 2, 8, 'Число транзисторов на кристалле удваивается каждые два года. Сколько миллиардов будет через 10 лет, если сейчас один миллиард?', '["32"]', 'За десять лет пройдёт пять удвоений.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 2, 9, 'Ток утечки 50 мА при питании 1,2 В. Сколько милливатт статической мощности он рассеивает?', '["60"]', 'P = U · I; ток в миллиамперах даёт мощность в милливаттах.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (14, 3, 'Упражнения: архитектуры и стандарты');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 3, 0, 'Сколько бит занимает команда базового формата RISC-V (RV32I)?', '["32"]', 'Базовые команды фиксированной длины.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 3, 1, 'Сколько целочисленных регистров общего назначения в RV32I?', '["32"]', 'x0…x31.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 3, 2, 'Сколько бит нужно, чтобы закодировать номер одного из 32 регистров?', '["5"]', '2⁵ = 32.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 3, 3, 'В команде R-типа: opcode 7 бит, rd 5, funct3 3, rs1 5, rs2 5. Сколько бит остаётся на funct7, если вся команда 32 бита?', '["7"]', 'Вычтите известные поля из 32.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 3, 4, 'Расширения набора команд помечают буквами: RV32IMAC. Сколько расширений указано помимо базового I?', '["3"]', 'M, A и C.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 3, 5, 'Сколько гибибайт можно адресовать 32-битным адресом, если адресуется каждый байт?', '["4"]', '2³² байтов = 4 ГиБ.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 3, 6, 'Сколько бит в числе двойной точности по стандарту IEEE 754?', '["64"]', 'Одинарная точность — 32 бита.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 3, 7, 'Сколько байт в слове из 32 бит?', '["4"]', 'Байт — 8 бит.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 3, 8, 'Требует ли использование открытой архитектуры RISC-V лицензионных отчислений за набор команд? Ответьте «да» или «нет».', '["нет"]', 'Открытый стандарт — главное отличие от закрытых наборов.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 3, 9, 'Во сколько раз вырастет плотность транзисторов на площади, если линейный размер уменьшить вдвое?', '["4"]', 'Площадь зависит от квадрата размера.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (14, 4, 'Упражнения: числа в двоичном виде');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 4, 0, 'Переведите двоичное 10110110 в десятичное.', '["182"]', 'Сложите степени двойки: 128 + 32 + 16 + 4 + 2.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 4, 1, 'Запишите десятичное 200 в двоичном виде (8 бит).', '["11001000","11001000"]', 'Вычитайте степени двойки от большей к меньшей: 128, 64, 8.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 4, 2, 'Переведите шестнадцатеричное AF в десятичное.', '["175"]', 'A = 10, F = 15; значение 16·10 + 15.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 4, 3, 'Запишите десятичное 255 в шестнадцатеричном виде без префикса.', '["ff","0xff"]', 'Старшая цифра — 15, младшая — 15.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 4, 4, 'Запишите −5 в 8-битном дополнительном коде.', '["11111011"]', 'Инвертируйте биты числа 5 и прибавьте единицу.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 4, 5, 'Какое десятичное число хранится в 8-битном дополнительном коде 10000001?', '["-127"]', 'Старший бит весит −128.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 4, 6, 'Чему равно наименьшее число в 8-битном дополнительном коде?', '["-128"]', 'Это единица в старшем бите и нули в остальных.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 4, 7, 'Четырёхбитные знаковые числа: 0111 + 0001. Какое десятичное число получится (с переполнением)?', '["-8"]', 'Результат 1000 — это −8 в дополнительном коде.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 4, 8, 'Расширьте 8-битное знаковое число F0 до 16 бит. Запишите результат шестнадцатеричным без префикса.', '["fff0","0xfff0"]', 'Знаковое расширение копирует старший бит.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 4, 9, 'Переведите двоичную дробь 0,101 в десятичную.', '["0.625"]', 'Веса разрядов: 1/2, 1/4, 1/8.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 4, 10, 'Чему равно 13, сдвинутое влево на 2 бита?', '["52"]', 'Сдвиг на n влево умножает на 2ⁿ.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 4, 11, 'Сколько шестнадцатеричных цифр нужно для записи одного байта?', '["2"]', 'Одна цифра — 4 бита.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (14, 5, 'Упражнения: текст и защита данных');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 5, 0, 'Каков десятичный код буквы «A» в ASCII?', '["65"]', 'Заглавные латинские буквы начинаются с 65.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 5, 1, 'Сколько байт занимает буква «я» в кодировке UTF-8?', '["2"]', 'Кириллица находится в диапазоне двухбайтовых символов.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 5, 2, 'Сколько байт занимает символ «€» (U+20AC) в UTF-8?', '["3"]', 'Код выше U+07FF, но ниже U+FFFF.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 5, 3, 'Сколько байт занимает смайлик U+1F600 в UTF-8?', '["4"]', 'Код выше U+FFFF.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 5, 4, 'Какой бит чётности нужно добавить к 1011001, чтобы общее число единиц стало чётным?', '["0"]', 'В слове четыре единицы — уже чётное число.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 5, 5, 'Расстояние Хэмминга между 10110 и 11100 — сколько позиций различаются?', '["2"]', 'Сравните слова побитово.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 5, 6, 'Каково минимальное расстояние Хэмминга между кодовыми словами, при котором можно исправить любую одиночную ошибку?', '["3"]', 'Для исправления t ошибок нужно 2t + 1.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 5, 7, 'Сколько контрольных битов минимум нужно коду Хэмминга для 11 информационных бит?', '["4"]', 'Должно выполняться 2^r ≥ m + r + 1.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 5, 8, 'Сумма трёх байт 12, F4 и 9A по модулю 256 — чему равна? Ответ в десятичном виде.', '["160"]', 'Сложите и отбросьте всё, что выше восьми бит.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 5, 9, 'Чему равна побитовая операция XOR байт 0F, F0 и AA? Ответ в десятичном виде.', '["85"]', 'XOR ассоциативен: сначала 0F ^ F0, затем ^ AA.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 5, 10, 'Данные 1101, порождающий многочлен 101 (деление в арифметике по модулю 2). Какой остаток CRC (2 бита) получится после дописывания двух нулей?', '["10"]', 'Делите 110100 на 101, заменяя вычитание на XOR.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 5, 11, 'Сколько символов Base64 (без символов дополнения) нужно для 9 байт данных?', '["12"]', 'Три байта превращаются в четыре символа.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (14, 18, 'Упражнения: кэш-память');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 18, 0, 'Кэш прямого отображения ёмкостью 32 КиБ, строка 64 байта. Сколько в нём строк?', '["512"]', 'Разделите ёмкость на размер строки.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 18, 1, 'Для этого кэша (32 КиБ, строка 64 байта, прямое отображение) — сколько бит в поле индекса?', '["9"]', 'Индексов столько же, сколько строк.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 18, 2, 'При 32-битном адресе, индексе 9 бит и смещении 6 бит — сколько бит занимает тег?', '["17"]', 'Тег — всё, что осталось.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 18, 3, 'Вероятность попадания 95 %, время попадания 1 нс, штраф за промах 100 нс. Чему равно среднее время доступа в наносекундах?', '["6"]', 'AMAT = время попадания + доля промахов · штраф.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 18, 4, 'Двухуровневый кэш: L1 — время 1 нс, промахов 10 %; L2 — время 10 нс, локальных промахов 20 %; память — 100 нс. Среднее время доступа в наносекундах?', '["4"]', 'Штраф L1 равен среднему времени доступа ко второму уровню.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 18, 5, 'Кэш на 4 строки по одному слову, прямое отображение (строка = адрес mod 4). Обращения к адресам 0, 4, 8, 0, 4, 8, 1, 5, 1, 5. Сколько попаданий?', '["0"]', 'Адреса 0, 4, 8 попадают в одну и ту же строку и вытесняют друг друга.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 18, 6, 'Тот же поток обращений, но кэш двухканальный ассоциативный на 4 строки (2 набора, адрес mod 2 выбирает набор), вытеснение LRU. Сколько попаданий?', '["2"]', 'В каждом наборе помещаются два блока.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 18, 7, 'Массив из 1024 целых по 4 байта читается подряд, кэш холодный, строка 64 байта. Сколько промахов?', '["64"]', 'Один промах загружает целую строку из 16 чисел.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 18, 8, 'Политика сквозной записи. Программа 100 раз записывает в одну и ту же ячейку. Сколько обращений в память по записи?', '["100"]', 'Каждая запись идёт и в кэш, и в память.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 18, 9, 'Политика обратной записи. Программа 100 раз записывает в одну и ту же ячейку, строка потом вытесняется. Сколько записей в память?', '["1"]', 'Память получает строку один раз, при вытеснении.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (14, 19, 'Упражнения: конвейер');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 19, 0, 'Пятиступенчатый конвейер без конфликтов выполняет 100 команд. Сколько тактов потребуется?', '["104"]', 'Первая команда выходит за 5 тактов, остальные — по одной на такт.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 19, 1, 'К чему стремится CPI идеального конвейера при очень длинной программе?', '["1"]', 'Каждый такт завершается одна команда.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 19, 2, 'Один такт однотактного процессора 800 пс. Конвейер: самая медленная ступень 200 пс плюс 20 пс на регистры. Программа длинная, конвейер завершает по команде за такт, разгон и опустошение не учитывайте. Во сколько раз быстрее работает конвейер? Ответ округлите до одного знака.', '["3.6"]', 'Отношение времён одной команды на период такта.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 19, 3, 'Сколько тактов простоя возникает между командой lw и следующей за ней командой, использующей загруженное значение, при наличии пересылки?', '["1"]', 'Данные готовы только после ступени памяти.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 19, 4, 'Доля переходов 20 %, штраф за неверный переход 2 такта, базовый CPI равен 1, предсказания нет (все переходы приводят к штрафу). Чему равен CPI?', '["1.4"]', 'CPI = 1 + доля · штраф.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 19, 5, 'Доля переходов 15 %, предсказатель точен на 90 %, штраф 10 тактов. Чему равен CPI (базовый — 1)?', '["1.15"]', 'Штраф платят только неверно угаданные переходы.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 19, 6, 'Двухбитный счётчик (0–1 — «не взят», 2–3 — «взят») стартует в 0, ветвь ведёт себя так: 1 1 0 1 1 1 0 0. Сколько предсказаний верно?', '["2"]', 'Предсказание делается до обновления счётчика; взят — прибавляем, не взят — вычитаем.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 19, 7, 'Двухканальный суперскалярный процессор в идеале выполняет сколько команд за такт (IPC)?', '["2"]', 'Два канала — две команды.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 19, 8, 'Сократит ли конвейер задержку выполнения одной команды по сравнению с однотактным процессором? Ответьте «да» или «нет».', '["нет"]', 'Конвейер повышает пропускную способность, но задержка одной команды не уменьшается.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 19, 9, 'Без пересылок и при записи в регистровый файл в первой половине такта команда, зависящая от предыдущей, должна ждать два такта. Сколько всего тактов простоя в серии из 5 команд, где каждая использует результат предыдущей?', '["8"]', 'Во всех четырёх парах соседних команд есть зависимость.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (14, 20, 'Упражнения: виртуальная память');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 20, 0, 'Размер страницы 4 КиБ. Сколько бит занимает смещение внутри страницы?', '["12"]', '4096 = 2¹².');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 20, 1, 'Адреса 32-битные, страницы по 4 КиБ. Сколько страниц в виртуальном адресном пространстве?', '["1048576"]', 'Номер страницы занимает 32 − 12 бит.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 20, 2, 'Сколько мебибайт занимает одноуровневая таблица страниц для 32-битного адреса, страниц 4 КиБ и записей по 4 байта?', '["4"]', 'Миллион записей по 4 байта.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 20, 3, 'Страницы 4 КиБ, запись таблицы 4 байта. Сколько записей помещается в одной странице таблицы?', '["1024"]', 'Разделите размер страницы на размер записи.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 20, 4, 'Таблица страниц: виртуальная страница 0x403 → физическая 0x12, 0x404 → 0x7F (страницы 4 КиБ). Чему равен физический адрес, соответствующий виртуальному 0x00403A10? Запишите шестнадцатеричное число без префикса.', '["12a10","0x12a10"]', 'Номер страницы — старшие 20 бит, смещение 0xA10 остаётся прежним.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 20, 5, 'TLB отвечает за 1 нс, память — 100 нс, при промахе TLB нужно два дополнительных обращения к памяти (двухуровневая таблица). Попаданий в TLB 98 %. Среднее время доступа в наносекундах?', '["105"]', 'К базовому доступу прибавьте штраф промахов.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 20, 6, 'Обращение к странице с флагом «только чтение» на запись приводит к исключению? Ответьте «да» или «нет».', '["да"]', 'Процессор сверяет права из записи таблицы.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 20, 7, 'Политика FIFO, 3 кадра. Ссылки на страницы: 1 2 3 4 1 2 5 1 2 3 4 5. Сколько страничных отказов?', '["9"]', 'Следите за очередью по порядку загрузки.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 20, 8, 'Те же ссылки, FIFO, но 4 кадра. Сколько отказов? (Сравните с предыдущим — это аномалия Белади.)', '["10"]', 'Больше кадров не гарантирует меньше отказов для FIFO.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 20, 9, 'Те же ссылки, политика LRU, 3 кадра. Сколько отказов?', '["10"]', 'Вытесняйте страницу, которую не использовали дольше всех.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (14, 21, 'Упражнения: ввод-вывод');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 21, 0, 'Диск передаёт данные со скоростью 100 МБ/с. За сколько секунд прочитается файл 500 МБ?', '["5"]', 'Разделите размер на скорость.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 21, 1, 'Регистры устройства расположены с шагом 4 байта по адресам с 0x1000 до 0x100F включительно. Сколько регистров?', '["4"]', 'Диапазон из 16 байт, по 4 байта на регистр.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 21, 2, 'Процессор 1 ГГц опрашивает устройство 100 раз в секунду, один опрос занимает 400 тактов. Какой процент процессорного времени уходит на опрос? Ответьте числом процентов.', '["0.004"]', 'Доля = опросы в секунду · такты / частота.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 21, 3, 'Обработка прерывания стоит 1000 тактов, их приходит 10 000 в секунду, процессор 2 ГГц. Какой процент времени уходит на прерывания?', '["0.5"]', '10 миллионов тактов в секунду из двух миллиардов.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 21, 4, 'Мегабайт передаётся по DMA блоками по 4 КиБ с прерыванием после каждого блока. Сколько прерываний?', '["256"]', 'Размер передачи делится на размер блока.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 21, 5, 'Последовательный порт 9600 бод, формат 8N1 (на байт уходит 10 бит). Сколько байт в секунду передаётся?', '["960"]', 'Делите скорость на число бит в кадре.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 21, 6, 'Диск вращается со скоростью 7200 оборотов в минуту. Чему равна средняя задержка вращения (половина оборота) в миллисекундах? Округлите до сотых.', '["4.17"]', 'Один оборот длится 60 / 7200 секунд.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 21, 7, 'Шина шириной 64 бита работает на 1600 миллионов передач в секунду. Какова пропускная способность в ГБ/с?', '["12.8"]', '8 байт за передачу.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 21, 8, 'Четыре диска по 1 ТБ собраны в RAID-5. Сколько полезных терабайт получится?', '["3"]', 'Одна ёмкость диска уходит на чётность.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 21, 9, 'Кольцевой буфер на 8 ячеек, индекс записи 2, индекс чтения 6. Сколько элементов в нём лежит?', '["4"]', 'Разница по модулю размера буфера.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (14, 22, 'Упражнения: параллелизм');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 22, 0, 'Закон Амдала: 90 % программы распараллеливается, процессоров 8. Каково ускорение? Округлите до сотых.', '["4.71"]', 'S = 1 / (s + (1 − s) / N).');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 22, 1, 'Какое максимальное ускорение возможно, если 5 % программы выполняется строго последовательно?', '["20"]', 'Предел при бесконечном числе процессоров — 1 / s.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 22, 2, 'Закон Густафсона: доля последовательной части 10 %, процессоров 16. Каково масштабируемое ускорение?', '["14.5"]', 'S = N − s · (N − 1).');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 22, 3, 'Ядро A прочитало строку (E), затем ядро B прочитало её же, затем ядро A записало в неё. В каком состоянии MESI окажется строка у ядра B? Ответьте одной буквой: M, E, S или I.', '["i"]', 'Запись приводит к инвалидации копий в других кэшах.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 22, 4, 'Сколько 4-байтных целых помещается в кэш-строке 64 байта?', '["16"]', 'Разделите размер строки на размер числа.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 22, 5, 'Сколько 32-битных чисел обрабатывает за одну инструкцию 256-битный векторный регистр?', '["8"]', 'Ширину регистра делим на ширину элемента.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 22, 6, 'В процессоре 4 ядра, у каждого 2 аппаратных потока. Сколько аппаратных потоков всего?', '["8"]', 'Перемножьте.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 22, 7, 'Последовательная версия работает 120 с, на 8 ядрах — 20 с. Какова эффективность распараллеливания (ускорение, делённое на число ядер)?', '["0.75"]', 'Ускорение 6, ядер 8.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 22, 8, 'Два потока выполняют по 2 команды, порядок внутри потока сохраняется. Сколько существует разных чередований?', '["6"]', 'Выберите, какие 2 места из 4 занимает первый поток.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 22, 9, 'Атомарна ли операция a++ над общей переменной без блокировок? Ответьте «да» или «нет».', '["нет"]', 'Она состоит из чтения, сложения и записи.');
